// Extract JSON from Ollama response
const ollamaResponse = $input.item.json.response;
let parsed;

try {
  // Try to find JSON in the response
  const jsonMatch = ollamaResponse.match(/\{[^}]+\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback: try to parse as-is
    parsed = JSON.parse(ollamaResponse);
  }
} catch (e) {
  // If parsing fails, extract manually
  const titleMatch = $input.item.json.request_text.match(/request\s+(?:the\s+)?(?:movie\s+)?(.+)/i);
  parsed = {
    media_type: "movie",
    title: titleMatch ? titleMatch[1].trim() : $input.item.json.request_text
  };
}

return {
  media_type: parsed.media_type || "movie",
  title: parsed.title,
  chat_id: $input.item.json.chat_id,
  original_request: $input.item.json.request_text
};

// Get the AI-selected result or fall back to first result
const results = $('Search Overseerr').item.json.results;
const requestedType = $('Extract Parsed Data').item.json.media_type;

// Try to get AI-selected media ID from previous node
let selectedMedia;
if ($input.item.json.selectedId) {
  // AI selected a specific result
  selectedMedia = results.find(r => r.id === $input.item.json.selectedId);
}

// Fallback: Find first match of requested type or just use first result
if (!selectedMedia) {
  selectedMedia = results.find(r => r.mediaType === requestedType) || results[0];
}

const mediaData = {
  tmdbId: selectedMedia.id,
  mediaType: selectedMedia.mediaType,
  title: selectedMedia.title || selectedMedia.name,
  year: selectedMedia.releaseDate ? new Date(selectedMedia.releaseDate).getFullYear() : (selectedMedia.firstAirDate ? new Date(selectedMedia.firstAirDate).getFullYear() : 'Unknown'),
  overview: selectedMedia.overview || 'No description available',
  posterPath: selectedMedia.posterPath ? `https://image.tmdb.org/t/p/w500${selectedMedia.posterPath}` : null,
  originalQuery: $('Extract Parsed Data').item.json.original_request,
  status: selectedMedia.mediaInfo?.status || 'unknown',
  chat_id: $('Extract Parsed Data').item.json.chat_id
};

return mediaData;

