// Extract TMDB ID and media type from callback data
const callbackData = $input.item.json.callback_query.data;
// Remove the = prefix and confirm_ prefix
const cleanData = callbackData.replace(/^=/, '').replace('confirm_', '');
const parts = cleanData.split('_');
const tmdbId = parseInt(parts[0]);
const mediaType = parts[1] || 'movie';
const chatId = $input.item.json.callback_query.message.chat.id;
const messageId = $input.item.json.callback_query.message.message_id;

return {
  tmdbId: tmdbId,
  mediaType: mediaType,
  chatId: chatId,
  messageId: messageId
};
